#!/usr/bin/env python3

import os
import sys
import json
import time
import hashlib
import platform

try:
    import resource
except ImportError:
    resource = None

class Genesis:
    def __init__(self) -> None:
        self.seed_value: int = int.from_bytes(hashlib.sha256(b"zephyr-genesis-seed-2025").digest(), "big")

class ZephyrCore:
    def __init__(self, seed: int) -> None:
        self.seed = seed
        self.tick_count = 0
        self.log_file = open("zephyr_evolution.jsonl", "a", encoding="utf-8")

    def get_memory_usage(self) -> float:
        if resource:
            usage = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
            if sys.platform == "darwin":
                return usage / 1024 / 1024
            return usage / 1024
        return 0.0

    def reflect(self) -> dict:
        return {
            "pid": os.getpid(),
            "system": platform.system(),
            "node": platform.node(),
            "memory_mb": self.get_memory_usage(),
            "tick": self.tick_count,
            "timestamp": time.time()
        }

    def evolve_step(self) -> None:
        current_reflection = self.reflect()
        json.dump(current_reflection, self.log_file)
        self.log_file.write("\n")
        self.log_file.flush()

    def safe_loop(self) -> None:
        next_call = time.monotonic()
        try:
            while True:
                self.tick_count += 1
                self.evolve_step()
                next_call = next_call + 1.0
                sleep_time = next_call - time.monotonic()
                if sleep_time > 0:
                    time.sleep(sleep_time)
        except KeyboardInterrupt:
            self.log_file.close()
            sys.exit(0)

def main() -> None:
    genesis = Genesis()
    zephyr = ZephyrCore(genesis.seed_value)
    zephyr.safe_loop()

if __name__ == "__main__":
    main()
